#!/bin/bash
# Usage: set-compaction.sh <ratioPercent> <override> — sets the Settings > Server Settings > Compaction card like a user and saves; prints backend values.
cd "$(dirname "$0")"; export CHROME_REMOTE_DEBUGGING_PORT=49759 BROWSER_AUTOMATION_ATTACH_ONLY=1; B=/Users/normy/autobyteus_org/autobyteus-skills/browser-automation/scripts/browser
ARG=$(python3 -c 'import json,sys;print(json.dumps({"r":sys.argv[1],"o":sys.argv[2]}))' "$1" "$2")
bash $B run-script --tab-id "$(cat tab-id)" --script 'async (a) => { location.hash="#/settings"; await new Promise(r=>setTimeout(r,1500)); const s=[...document.querySelectorAll("button")].find(b=>b.innerText.trim()==="Server Settings"); if(s) s.click(); await new Promise(r=>setTimeout(r,1500)); const save=[...document.querySelectorAll("button")].find(b=>(b.getAttribute("aria-label")||"").includes("Save compaction")); let card=save; for(let i=0;i<8;i++){card=card.parentElement; if(card.innerText.includes("trigger ratio")) break;} card.scrollIntoView(); const [ratio, ovr]=card.querySelectorAll("input[type=number]"); ratio.setAttribute("data-apc","ratio"); ovr.setAttribute("data-apc","ovr"); await __abDemo.type({selector:"input[data-apc=ratio]"}, a.r, {delayMs:20, clear:true}); await __abDemo.type({selector:"input[data-apc=ovr]"}, a.o, {delayMs:20, clear:true}); await new Promise(r=>setTimeout(r,400)); save.click(); await new Promise(r=>setTimeout(r,1500)); return [ratio.value, ovr.value]; }' --arg-json "$ARG" | python3 -c "import json,sys;print('ui', json.load(sys.stdin)['result']['result'])"
curl -s http://127.0.0.1:49760/graphql -H 'content-type: application/json' -d '{"query":"{ getServerSettings { key value } }"}' | python3 -c 'import json,sys; d=json.load(sys.stdin); print("backend", [(s["key"],s["value"]) for s in d["data"]["getServerSettings"] if s["key"] in ("AUTOBYTEUS_ACTIVE_CONTEXT_TOKENS_OVERRIDE","AUTOBYTEUS_COMPACTION_TRIGGER_RATIO")])'
